## 1. Declare the route

Append an entry to the end of the existing `defineAppRoutes([...])` array in `client/routes.ts`. Leave the existing routes (home, sign-in pages) as they are, and do not overwrite the whole file. Add the icon to the existing `lucide-react` import at the top of the file:

```ts
import { FolderKanban, Home } from 'lucide-react';
```

The projects list page to append, with three child routes for create, detail and edit:

```ts
const appRoutes: AppClientRouteContribution = defineAppRoutes([
  // … existing routes (home, sign-in pages); keep them
  {
    name: 'projects',
    path: '/projects',
    auth: 'required',
    authz: 'skip',
    navigation: { title: 'navigation.projects', icon: FolderKanban },
    componentLoader: () => import('./pages/projects/index.js'),
    children: [
      {
        // /projects/new: create dialog (RouteDialog)
        name: 'project-new',
        path: 'new',
        componentLoader: () => import('./pages/projects/new.js'),
      },
      {
        // /projects/:projectId: detail drawer (RouteDrawer)
        name: 'project-detail',
        path: ':projectId',
        componentLoader: () => import('./pages/projects/detail/index.js'),
        children: [
          {
            // /projects/:projectId/edit: edit dialog, stacked on the detail drawer
            name: 'project-edit',
            path: 'edit',
            componentLoader: () => import('./pages/projects/detail/edit.js'),
          },
        ],
      },
    ],
  },
]);

## 2. Migrations and seeds

A migration creates structure. A seed inserts the records the application needs in order to run. Neither does the other's job, and a seed is never sample or demonstration content.

```ts
// database/main/migrations/202609020001_create_orders.ts
import { defineMigration, type MigrationDefinition } from '@nocobase/db';

const migration: MigrationDefinition = defineMigration({
  name: '202609020001_create_orders',

  async up({ builder }) {
    await builder.createCollection('orders', (collection) => {
      collection.increments('id');
      collection.string('orderNo', { length: 64, nullable: false });
      collection.string('status', { length: 32, nullable: false });
      collection.datetime('createdAt', { nullable: false });
      collection.unique('orderNo');
      collection.index('status');
    });
  },

  async down({ builder }) {
    await builder.dropCollection('orders');
  },
});

export default migration;
```

```ts
// database/main/seeds/202609030002_default_order_statuses.ts
import { defineSeed } from '@nocobase/db';

export default defineSeed({
  name: '202609030002_default_order_statuses',

  async run({ repository }) {
    await repository('orderStatuses').upsertOne({
      filter: { code: 'draft' },
      create: { code: 'draft', title: 'Draft' },
      update: { title: 'Draft' },
    });
  },
});
```

Apply both with `pnpm db:apply`, adding `--connection <name>` for a non-default connection or `--all` for every managed one.

async list() {
    const [records, targets] = await Promise.all([
        this.store.list(),
        this.store.listTargets(),
    ]);
    const byId = new Map(targets.map((target) => [target.id, target]));
    return Promise.all(records.map(async (record) => {
        const target = byId.get(record.id);
        return {
            ...record,
            targetState: target
                ? ((await this.targets.describe(target.type, target.config))
                    .state ?? 'invalid')
                : 'missing',
            targetSummary: target
                ? await this.targets.describe(target.type, target.config)
                : { targetLabel: record.targetType, state: 'missing' },
        };
    }));
}
